def _extract_text_content(content: Any) -> str:
    """Normalize Grok/Claude-style content into a single plain-text string."""
    if content is None:
        return ""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts: list[str] = []
        for block in content:
            if isinstance(block, str):
                if block:
                    parts.append(block)
                continue
            if not isinstance(block, dict):
                continue
            bt = block.get("type")
            if bt in ("text", "input_text", "output_text", "summary_text") or "text" in block:
                text = block.get("text")
                if text:
                    parts.append(str(text))
            elif bt == "content":
                nested = block.get("content")
                nested_text = _extract_text_content(nested)
                if nested_text:
                    parts.append(nested_text)
        return "".join(parts)
    if isinstance(content, dict):
        if "text" in content and isinstance(content.get("text"), str):
            return content["text"]
        if "content" in content:
            return _extract_text_content(content.get("content"))
    return str(content)


