def expand_grok_event(raw_event: dict, fallback_ts: str, default_model: str | None = None) -> list[dict]:
    """Convert one Grok Build chat_history.jsonl line to contest events.

    Schema (verified against real ~/.grok/sessions/*/chat_history.jsonl):
      - type: system | user | assistant | reasoning | tool_result
      - user.content: list of {type:text, text:...} (often wraps <user_query>)
      - assistant.content: str; assistant.tool_calls: [{id,name,arguments}]
      - reasoning.summary: [{type:summary_text, text:...}]  (thinking)
      - tool_result: {tool_call_id, content}
    """
    out: list[dict] = []
    etype = (raw_event.get("type") or "").lower()

    if etype in ("system", "developer"):
        # System prompt is huge and not useful for contest review.
        return out

    if etype == "user":
        text = _extract_text_content(raw_event.get("content")).strip()
        if text:
            out.append({"ts": fallback_ts, "role": "user", "text": text})
        return out

    if etype == "reasoning":
        thinking_parts: list[str] = []
        for block in raw_event.get("summary") or []:
            if isinstance(block, dict):
                t = block.get("text") or ""
                if t:
                    thinking_parts.append(str(t))
            elif isinstance(block, str) and block:
                thinking_parts.append(block)
        thinking = "\n".join(thinking_parts).strip()
        if thinking:
            ev: dict[str, Any] = {"ts": fallback_ts, "role": "assistant", "thinking": thinking}
            model = raw_event.get("model_id") or default_model
            if model:
                ev["model"] = model
            out.append(ev)
        return out

    if etype == "assistant":
        model = raw_event.get("model_id") or default_model
        text = _extract_text_content(raw_event.get("content")).strip()
        common: dict[str, Any] = {"ts": fallback_ts, "role": "assistant"}
        if model:
            common["model"] = model
        if text:
            out.append({**common, "text": text})
        for tc in raw_event.get("tool_calls") or []:
            if not isinstance(tc, dict):
                continue
            out.append({
                "ts": fallback_ts,
                "role": "tool",
                "tool_name": tc.get("name") or tc.get("tool_name") or "unknown",
                "tool_call_id": tc.get("id") or tc.get("tool_call_id") or f"call_{len(out)}",
                "input": _parse_tool_arguments(tc.get("arguments") if "arguments" in tc else tc.get("input")),
                "output": None,
            })
        return out

    if etype in ("tool_result", "function_call_output", "tool"):
        # Standalone tool result line (Grok) or tool_use-like line.
        if etype == "tool" and raw_event.get("name") and not raw_event.get("tool_call_id"):
            out.append({
                "ts": fallback_ts,
                "role": "tool",
                "tool_name": raw_event.get("name", "unknown"),
                "tool_call_id": raw_event.get("id", f"call_{len(out)}"),
                "input": _parse_tool_arguments(raw_event.get("arguments") or raw_event.get("input")),
                "output": None,
            })
            return out
        tool_call_id = (
            raw_event.get("tool_call_id")
            or raw_event.get("toolCallId")
            or raw_event.get("call_id")
            or f"call_{len(out)}"
        )
        result_content = raw_event.get("content")
        if result_content is None:
            result_content = raw_event.get("output")
        out.append({
            "ts": fallback_ts,
            "role": "tool",
            "tool_name": "<result>",
            "tool_call_id": tool_call_id,
            "input": None,
            "output": result_content,
            "is_error": bool(raw_event.get("is_error") or raw_event.get("isError")),
        })
        return out

    return out


def grok_home() -> Path:
    return Path(os.environ.get("GROK_HOME") or (Path.home() / ".grok"))


def find_grok_session_dir(session_id: str, cwd: str | None = None) -> Path | None:
    """Locate ~/.grok/sessions/<encoded-cwd>/<session_id>/ for a session."""
    if not session_id:
        return None
    sessions_root = grok_home() / "sessions"
    if not sessions_root.is_dir():
        return None

    candidates: list[Path] = []
    if cwd:
        try:
            resolved = str(Path(cwd).resolve())
        except Exception:
            resolved = cwd
        for variant in (resolved, cwd):
            encoded = quote(variant, safe="")
            candidates.append(sessions_root / encoded / session_id)
            # Some builds may leave the path partially encoded.
            candidates.append(sessions_root / quote(variant, safe="/") / session_id)

    for cand in candidates:
        if (cand / "chat_history.jsonl").is_file():
            return cand

    # Fallback: scan all cwd groups (also handles hashed group names with .cwd).
    try:
        for group in sessions_root.iterdir():
            if not group.is_dir() or group.name.startswith("."):
                continue
            cand = group / session_id
            if (cand / "chat_history.jsonl").is_file():
                return cand
            # Rare: session_id stored as file stem under group.
            direct = group / f"{session_id}.jsonl"
            if direct.is_file():
                return group
    except Exception:
        return None
    return None


