def _iter_grok_sessions() -> list[tuple[str, str, Path]]:
    """Return [(session_id, cwd, chat_history_path), ...] from ~/.grok/sessions."""
    grok_home = Path(subprocess.os.environ.get("GROK_HOME") or (Path.home() / ".grok"))
    sessions_root = grok_home / "sessions"
    if not sessions_root.is_dir():
        return []

    found: list[tuple[str, str, Path]] = []
    for group in sorted(sessions_root.iterdir()):
        if not group.is_dir() or group.name.startswith("."):
            continue
        # Preferred: decode URL-encoded cwd group name.
        cwd = ""
        try:
            from urllib.parse import unquote
            cwd = unquote(group.name)
            if not cwd.startswith("/"):
                cwd = ""
        except Exception:
            cwd = ""
        cwd_file = group / ".cwd"
        if cwd_file.is_file():
            try:
                cwd = cwd_file.read_text(encoding="utf-8").strip() or cwd
            except Exception:
                pass

        for sid_dir in sorted(group.iterdir()):
            if not sid_dir.is_dir():
                continue
            history = sid_dir / "chat_history.jsonl"
            if not history.is_file():
                continue
            session_cwd = cwd
            summary_path = sid_dir / "summary.json"
            if summary_path.is_file():
                try:
                    summary = json.loads(summary_path.read_text(encoding="utf-8"))
                    session_cwd = (summary.get("info") or {}).get("cwd") or summary.get("cwd") or session_cwd
                except Exception:
                    pass
            found.append((sid_dir.name, session_cwd or str(Path.cwd()), history))
    return found


