    print(f"Backfill tools: {tools}")
    print()

    success = 0
    skipped = 0
    if tools in ("all", "claude-code", "claude"):
        s, k = _backfill_claude(dest, core_py, team_id, github_login)
        success += s
        skipped += k
    if tools in ("all", "grok-build", "grok"):
        s, k = _backfill_grok(dest, core_py, team_id, github_login)
        success += s
        skipped += k

    print(f"\nBackfill done: {success} imported, {skipped} skipped (already captured or empty).")
    if success > 0:
        print("Next: git add logs/ && git commit -s -m 'logs: backfill history' && git push")
    return 0
